def f(x):
    return x**2

a = 2.0

for h in [1, 0.1, 0.01, 0.001, 0.0001]:
    quotient = (f(a + h) - f(a)) / h
    print(h, quotient)

def f(x):
    return x**3 - x - 1

left = 1.0
right = 2.0

for step in range(20):
    mid = (left + right) / 2
    if f(left) * f(mid) <= 0:
        right = mid
    else:
        left = mid

    print(step + 1, left, right, (left + right) / 2)

def f(x):
    return 4 / (1 + x**2)

def midpoint_rule(a, b, n):
    dx = (b - a) / n
    total = 0.0
    for k in range(1, n + 1):
        midpoint = a + (k - 0.5) * dx
        total += f(midpoint)
    return total * dx

for n in [4, 8, 16, 32, 64, 128]:
    print(n, midpoint_rule(0, 1, n))

