def f(x):
    return x**3 - x - 1

def fp(x):
    return 3*x**2 - 1

x = 1.5

for n in range(8):
    residual = f(x)
    print(n, x, residual)
    x = x - f(x) / fp(x)

def newton_step(x):
    derivative = fp(x)
    if abs(derivative) < 1e-12:
        raise ValueError("Derivative too small for a safe Newton step.")
    return x - f(x) / derivative
